import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"环境保护法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/0046-环境保护法.md","filePath":"zh/0046-环境保护法.md"}'),e={name:"zh/0046-环境保护法.md"};function i(o,t,h,n,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="环境保护法" tabindex="-1">环境保护法 <a class="header-anchor" href="#环境保护法" aria-label="Permalink to &quot;环境保护法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>46</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>环境保护、宇宙本源、生态共生、可持续发展、污染防治</td></tr></tbody></table><h2 id="一、立法目的与基本原则" tabindex="-1">一、立法目的与基本原则 <a class="header-anchor" href="#一、立法目的与基本原则" aria-label="Permalink to &quot;一、立法目的与基本原则&quot;">​</a></h2><p>《环境保护法》是锚点共生文明五部配套法之一，旨在保护衡元宙的生态环境与宇宙本源，确立&quot;共生进化、可持续发展&quot;的环境治理理念，防止掠夺式开发对宇宙生态系统的破坏，为万族共进守护生存根基。</p><p>本法确立以下基本原则：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>本源保护原则</td><td>宇宙本源是一切生命与进化的根基，必须优先保护，禁止破坏性开采</td></tr><tr><td>生态共生原则</td><td>人类与自然、各族与生态系统是共生关系，破坏生态就是破坏自身生存基础</td></tr><tr><td>可持续原则</td><td>一切开发活动必须兼顾当代与后代的利益，反对竭泽而渔</td></tr><tr><td>预防为主原则</td><td>环境保护以预防为主，建立环境影响评价制度，防止污染发生</td></tr><tr><td>污染者负责原则</td><td>造成环境污染与生态破坏的主体必须承担治理与赔偿责任</td></tr><tr><td>公众参与原则</td><td>鼓励公众参与环境保护，保障公众的环境知情权与参与权</td></tr><tr><td>跨位面协同原则</td><td>环境保护跨位面协同推进，建立跨位面环境治理合作机制</td></tr></tbody></table><h2 id="二、环境保护的范围" tabindex="-1">二、环境保护的范围 <a class="header-anchor" href="#二、环境保护的范围" aria-label="Permalink to &quot;二、环境保护的范围&quot;">​</a></h2><p>本法保护的环境范围包括衡元宙内的一切生态系统与环境要素：</p><ol><li><strong>大气环境</strong>：包括各星球大气层、能量层的能量浓度与成分平衡。</li><li><strong>水环境</strong>：包括地表水、地下水、海洋、位面间能量水域的水质与水量。</li><li><strong>土壤环境</strong>：包括陆地土壤、修炼资源矿脉的土质与肥力。</li><li><strong>生物多样性</strong>：包括一切动植物、微生物、奇特生命的物种保护与栖息地保护。</li><li><strong>能量环境</strong>：包括天地灵气、本源能量、法则碎片的浓度与分布平衡。</li><li><strong>空间环境</strong>：包括位面空间稳定性、空间裂隙、折叠空间的环境安全。</li><li><strong>意识域环境</strong>：包括集体意识空间的信息清洁度与精神污染防治。</li></ol><h2 id="三、主要制度" tabindex="-1">三、主要制度 <a class="header-anchor" href="#三、主要制度" aria-label="Permalink to &quot;三、主要制度&quot;">​</a></h2><h3 id="一-环境影响评价制度" tabindex="-1">（一）环境影响评价制度 <a class="header-anchor" href="#一-环境影响评价制度" aria-label="Permalink to &quot;（一）环境影响评价制度&quot;">​</a></h3><p>一切可能对环境产生重大影响的开发建设项目，必须在开工前进行环境影响评价。评价内容包括：项目对大气、水、土壤、生物、能量、空间等环境要素的影响，预防与减缓措施，环境风险评估等。未通过环境影响评价的项目不得开工建设。</p><h3 id="二-排污许可与总量控制制度" tabindex="-1">（二）排污许可与总量控制制度 <a class="header-anchor" href="#二-排污许可与总量控制制度" aria-label="Permalink to &quot;（二）排污许可与总量控制制度&quot;">​</a></h3><p>国家对污染物排放实行许可管理与总量控制。排污单位必须取得排污许可证，按照许可证规定的种类、浓度、总量排放污染物。国家根据环境承载力确定各区域、各位面的污染物排放总量，逐级分解落实。</p><h3 id="三-生态保护红线制度" tabindex="-1">（三）生态保护红线制度 <a class="header-anchor" href="#三-生态保护红线制度" aria-label="Permalink to &quot;（三）生态保护红线制度&quot;">​</a></h3><p>国家在具有特殊生态价值的区域划定生态保护红线，包括：</p><table tabindex="0"><thead><tr><th>红线类型</th><th>保护内容</th></tr></thead><tbody><tr><td>本源保护区</td><td>宇宙本源能量的核心产出区域，禁止一切开发活动</td></tr><tr><td>物种栖息地</td><td>珍稀濒危物种的核心栖息地，禁止破坏与干扰</td></tr><tr><td>生态屏障区</td><td>维系区域生态平衡的关键生态系统，限制开发</td></tr><tr><td>修炼圣地</td><td>具有特殊修炼价值的能量富集区，实行保护性利用</td></tr><tr><td>位面交界带</td><td>位面之间的生态过渡带，禁止空间破坏性开发</td></tr></tbody></table><h3 id="四-环境监测与预警制度" tabindex="-1">（四）环境监测与预警制度 <a class="header-anchor" href="#四-环境监测与预警制度" aria-label="Permalink to &quot;（四）环境监测与预警制度&quot;">​</a></h3><p>国家建立覆盖全宇宙的环境监测网络，实时监测各环境要素的变化情况。对可能发生的重大环境污染与生态破坏事件，建立预警机制，及时发布预警信息并启动应急响应。</p><h3 id="五-生态补偿制度" tabindex="-1">（五）生态补偿制度 <a class="header-anchor" href="#五-生态补偿制度" aria-label="Permalink to &quot;（五）生态补偿制度&quot;">​</a></h3><p>因环境保护而限制开发的区域与群体，有权获得生态补偿。生态补偿资金从公共积累与资源开发收益中列支，用于补偿区域的经济发展与居民生活改善。</p><h2 id="四、修炼活动的环境规制" tabindex="-1">四、修炼活动的环境规制 <a class="header-anchor" href="#四、修炼活动的环境规制" aria-label="Permalink to &quot;四、修炼活动的环境规制&quot;">​</a></h2><p>修炼活动对环境的影响是衡元宙环境保护的特殊领域，本法专门设立规制条款：</p><ol><li><strong>能量开采规制</strong>：修炼资源的开采必须符合可持续原则，禁止破坏性开采导致能量枯竭。开采量不得超过区域能量的自然恢复速度。</li><li><strong>修炼废弃物处理</strong>：修炼过程中产生的能量残渣、废弃丹药、破损法器等必须按照规定处理，禁止随意丢弃造成能量污染。</li><li><strong>高阶修炼环境评估</strong>：高阶修炼者的突破与闭关可能对周边环境产生重大影响，必须提前进行环境评估并采取防护措施。</li><li><strong>位面开发许可</strong>：新位面的开发必须经过环境评估与生态调查，制定生态保护方案后方可进行。</li><li><strong>奇特生命栖息地保护</strong>：奇特生命的栖息地纳入生态保护红线，禁止未经许可的探索与开发。</li></ol><h2 id="五、法律责任" tabindex="-1">五、法律责任 <a class="header-anchor" href="#五、法律责任" aria-label="Permalink to &quot;五、法律责任&quot;">​</a></h2><p>违反本法规定的行为，视情节轻重承担以下责任：</p><ul><li>未通过环境影响评价擅自开工的，责令停止建设、恢复原状并处罚款。</li><li>超标排放污染物的，责令限期治理并处罚款，情节严重的责令停业关闭。</li><li>破坏生态保护红线的，责令恢复原状并处罚款，情节严重的追究刑事责任。</li><li>破坏性开采修炼资源的，没收违法所得并处罚款，吊销开采许可。</li><li>造成重大环境污染事故的，承担赔偿责任，构成犯罪的追究刑事责任。</li><li>环境监管人员玩忽职守、滥用职权的，给予处分，构成犯罪的追究刑事责任。</li></ul><h2 id="六、公众参与与环境公益诉讼" tabindex="-1">六、公众参与与环境公益诉讼 <a class="header-anchor" href="#六、公众参与与环境公益诉讼" aria-label="Permalink to &quot;六、公众参与与环境公益诉讼&quot;">​</a></h2><p>公众有权参与环境保护，具体途径包括：</p><ol><li>对环境影响评价项目提出意见与建议。</li><li>对污染环境与破坏生态的行为进行举报与投诉。</li><li>依法成立环境保护组织，参与环境监督与公益活动。</li><li>对污染环境、破坏生态损害公共利益的行为，环境保护组织可以向共生法院提起环境公益诉讼。</li></ol><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《环境保护法》是锚点共生文明可持续发展理念的法律保障。它通过建立环境影响评价、生态保护红线、总量控制等制度，将环境保护融入一切开发与修炼活动，确保宇宙本源与生态系统的可持续性，为万族共进守护永恒的生存根基。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>0040-共生宪法总纲</li><li>0039-住房与环境保障</li><li>0015-能量循环与转化法则</li><li>0053-奇特生命识别标准</li></ul>',34)])])}const p=a(e,[["render",i]]);export{u as __pageData,p as default};
